function minIncrementOperations(nums, k) {
  const n = nums.length;
  const dp = new Array(n).fill(0);

  for (let i = 0; i < n; i++) {
    const cost = Math.max(0, k - nums[i]);
    let previous = 0;
    if (i >= 3) {
      previous = Math.min(dp[i - 1], dp[i - 2], dp[i - 3]);
    }
    dp[i] = cost + previous;
  }

  return Math.min(dp[n - 1], dp[n - 2], dp[n - 3]);
}

