function minIncrementOperations(nums, k) {
  // Try every set of positions that end up at least k; every window of three must contain one of them.
  const n = nums.length;
  let best = Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    let ok = true;
    for (let start = 0; start + 3 <= n && ok; start++) {
      if (!(mask >> start & 7)) ok = false;
    }
    if (!ok) continue;
    let total = 0;
    for (let i = 0; i < n; i++) if (mask >> i & 1) total += Math.max(0, k - nums[i]);
    best = Math.min(best, total);
  }
  return best;
}

