function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = pick(1500, 2000);
    const k = pick(0, 1000000000);
    const nums = Array.from({ length: n }, () => rand() < 0.2 ? pick(k, 1000000000) : pick(0, 1000000000));
    return [nums, k];
  }
  const n = pick(3, 12);
  const top = [1, 5, 10, 1000000000][Math.floor(rand() * 4)];
  const k = rand() < 0.1 ? 0 : pick(0, top);
  const nums = Array.from({ length: n }, () => rand() < 0.15 ? k : pick(0, top));
  return [nums, k];
}
